BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee8a0000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'Luma allowance SQL fixture'),(pg_temp.i(2),'Luma model other fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','luma-allowance-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,103)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),case when n=102 then'viewer'else'admin'end from generate_series(101,103)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'Luma model SQL property'),(pg_temp.i(202),pg_temp.i(2),'Luma model other property');
-- Community Brain requires explicit grants even within the same organization.
select public.brain_set_access(pg_temp.i(101),pg_temp.i(201),pg_temp.i(101),array['read','manage'],null,false,'Fixture model evidence management');
select public.brain_set_access(pg_temp.i(101),pg_temp.i(201),pg_temp.i(102),array['read'],null,false,'Fixture model evidence read access');
insert into public.lumaleasing_config(id,property_id,api_key,is_active)values(pg_temp.i(301),pg_temp.i(201),'synthetic-model-key',true);
insert into public.conversations(id,property_id,channel)values(pg_temp.i(401),pg_temp.i(201),'widget');
create function pg_temp.claim(n int,body text default '{"messages":[{"role":"user","content":"Exact private request"}]}')returns jsonb language sql as $$select public.claim_recorded_luma_request(pg_temp.i(201),pg_temp.i(n),'chat',body,'synthetic-actor',encode(sha256(convert_to('synthetic-model-key','UTF8')),'hex'))$$;
create function pg_temp.model(n int,purpose text default'answer',params jsonb default'{"model":"fixture","messages":[{"role":"user","content":"Exact private prompt"}],"max_tokens":400}',lim bigint default 100000)returns jsonb language sql as $$select public.claim_luma_model(pg_temp.i(201),pg_temp.i(n),(select lease_token from public.luma_requests where property_id=pg_temp.i(201)and request_id=pg_temp.i(n)),purpose,params,jsonb_build_object('conversationId',pg_temp.i(401),'modeRevision',0),2000,lim)$$;
create function pg_temp.finish(n int,response jsonb default'{"content":"Actual saved response"}',status int default 200)returns boolean language sql as $$select public.finish_recorded_luma_request(pg_temp.i(201),pg_temp.i(n),(select lease_token from public.luma_requests where property_id=pg_temp.i(201)and request_id=pg_temp.i(n)),response,status)$$;
create function pg_temp.review(n int,target int,op text,actor int default 101)returns jsonb language sql as $$select public.review_luma_request(pg_temp.i(n),pg_temp.i(actor),pg_temp.i(201),pg_temp.i(target),jsonb_build_object('operation',op,'sourceHash',encode(sha256(convert_to(public.luma_request_source(pg_temp.i(201),pg_temp.i(target))::text,'UTF8')),'hex'),'reason','Exact retained evidence checked'))$$;
create function pg_temp.fixture_intent_day()returns trigger language plpgsql as $$begin new.created_at:=((now()at time zone'UTC')::date+time'12:00')at time zone'UTC';if new.request_id=pg_temp.i(505)then new.reservation_bucket:=null;elsif new.request_id=pg_temp.i(506)then new.created_at:=new.created_at+interval'1 day';end if;return new;end$$;
create trigger fixture_intent_day before insert on public.luma_model_intents for each row execute function pg_temp.fixture_intent_day();
set local role service_role;
insert into st values('request',pg_temp.claim(501));
insert into st values('intent',pg_temp.model(501));
select pg_temp.check_it((select used=2000 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'reserve complete upper bound before invocation');
insert into st values('response',jsonb_build_object('id','provider-known','choices',jsonb_build_array(jsonb_build_object('message',jsonb_build_object('content','Exact original answer'))),'usage',jsonb_build_object('prompt_tokens',20,'completion_tokens',2,'total_tokens',22)));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='intent'),pg_temp.i(201),pg_temp.i(501),(select lease_token from public.luma_requests where request_id=pg_temp.i(501)),'received',(select v from st where k='response'),null);
select pg_temp.check_it((select used=22 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'completed call releases unused reservation');
select pg_temp.check_it((select reserved_units=2000 and charged_units=22 and released_units=1978 and allowance_before=2000 and allowance_after=22 from public.luma_model_allowance_settlements where model_id=(select(v->>'id')::uuid from st where k='intent')),'immutable adjustment preserves before and after accounting');
select pg_temp.check_it((select response=(select v from st where k='response')from public.luma_model_results where id=(select(v->>'id')::uuid from st where k='intent')),'provider response unchanged');
select pg_temp.check_it((select reserved_units=2000 from public.luma_model_intents where id=(select(v->>'id')::uuid from st where k='intent')),'original reservation unchanged');
select set_config('p11.luma_request_scope','unrelated-caller',true);
select pg_temp.check_it(public.settle_luma_model_allowance(pg_temp.i(201),(select(v->>'id')::uuid from st where k='intent'))->>'state'='replayed','repeat settlement cannot double-credit');
select pg_temp.check_it(current_setting('p11.luma_request_scope',true)='unrelated-caller','caller scope unchanged');
select pg_temp.check_it(public.settle_luma_model_allowance(pg_temp.i(202),(select(v->>'id')::uuid from st where k='intent'))->>'state'='not_found','wrong community cannot settle another charge');
select pg_temp.check_it((select used=22 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'replay and foreign attempt change no accounting');
select pg_temp.check_it(not public.reserve_luma_allowance(pg_temp.i(201),'ai:'||to_char(now()at time zone'UTC','YYYY-MM-DD'),2000,2001,now()+interval'2 days'),'same configured admission limit still enforced');
insert into st values('unknown-request',pg_temp.claim(502));insert into st values('unknown-intent',pg_temp.model(502));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='unknown-intent'),pg_temp.i(201),pg_temp.i(502),(select lease_token from public.luma_requests where request_id=pg_temp.i(502)),'unknown',null,'provider_timeout');
select pg_temp.check_it((select used=2022 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'unknown provider cost keeps complete reservation');
insert into st values('incomplete-request',pg_temp.claim(503));insert into st values('incomplete-intent',pg_temp.model(503));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='incomplete-intent'),pg_temp.i(201),pg_temp.i(503),(select lease_token from public.luma_requests where request_id=pg_temp.i(503)),'received','{"id":"provider-incomplete","choices":[],"usage":{"total_tokens":22}}',null);
select pg_temp.check_it((select used=4022 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'incomplete usage cannot manufacture a credit');
select pg_temp.check_it((select count(*)=1 from public.luma_model_allowance_settlements where property_id=pg_temp.i(201)),'only confirmed complete usage settled');
insert into st values('overrun-request',pg_temp.claim(504));insert into st values('overrun-intent',pg_temp.model(504));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='overrun-intent'),pg_temp.i(201),pg_temp.i(504),(select lease_token from public.luma_requests where request_id=pg_temp.i(504)),'received','{"id":"provider-overrun","choices":[],"usage":{"prompt_tokens":2000,"completion_tokens":100,"total_tokens":2100}}',null);
select pg_temp.check_it((select used=6122 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'actual overrun increases used allowance instead of hiding cost');
insert into st values('legacy-request',pg_temp.claim(505));insert into st values('legacy-intent',pg_temp.model(505));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='legacy-intent'),pg_temp.i(201),pg_temp.i(505),(select lease_token from public.luma_requests where request_id=pg_temp.i(505)),'received','{"id":"provider-legacy","choices":[],"usage":{"prompt_tokens":20,"completion_tokens":2,"total_tokens":22}}',null);
select pg_temp.check_it((select used=8122 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'historical receipt requires a reviewed reservation day');
select pg_temp.check_it(public.settle_luma_model_allowance(pg_temp.i(201),(select(v->>'id')::uuid from st where k='legacy-intent'),'ai:'||to_char(now()at time zone'UTC','YYYY-MM-DD'))->>'state'='settled','confirmed historical reservation day supports an explicit correction');
select pg_temp.check_it((select reservation_bucket is null from public.luma_model_intents where id=(select(v->>'id')::uuid from st where k='legacy-intent')),'historical intent remains unchanged after correction');
insert into st values('midnight-request',pg_temp.claim(506));insert into st values('midnight-intent',pg_temp.model(506));
select public.finish_luma_model((select(v->>'id')::uuid from st where k='midnight-intent'),pg_temp.i(201),pg_temp.i(506),(select lease_token from public.luma_requests where request_id=pg_temp.i(506)),'received','{"id":"provider-midnight","choices":[],"usage":{"prompt_tokens":20,"completion_tokens":2,"total_tokens":22}}',null);
select pg_temp.check_it((select used=6166 from public.luma_allowances where property_id=pg_temp.i(201)and bucket like'ai:%'),'transaction crossing UTC midnight settles its exact reserved day');
select pg_temp.check_it(not has_table_privilege('authenticated','public.luma_model_allowance_settlements','select')and not has_table_privilege('service_role','public.luma_model_allowance_settlements','insert')and not has_function_privilege('anon','public.settle_luma_model_allowance(uuid,uuid,text)','execute')and not has_function_privilege('authenticated','public.settle_luma_model_allowance(uuid,uuid,text)','execute')and not has_function_privilege('community_brain_worker','public.settle_luma_model_allowance(uuid,uuid,text)','execute'),'no browser, worker or direct ledger-write grant');
reset role;
select pg_temp.throws('update public.luma_model_allowance_settlements set charged_units=1','settled receipt cannot be rewritten');
select pg_temp.throws('delete from public.luma_model_allowance_settlements','settled receipt cannot be removed');
select 'Assertions passed: '||n from assertion_count;
rollback;
